  "answerOptions" : [ {
    "id" : 806,
    "text" : "Define a `TaxCalculator` interface, one implementation per country, and inject the chosen one.",
    "explanation" : "This is the Strategy pattern: the algorithm varies independently of the client.",
    "isCorrect" : true,
    "invalid" : false
  }, {
    "id" : 807,
    "text" : "Add a `switch` over the country code inside the billing service.",
