  "type" : "multiple-choice",
  "id" : 266,
  "title" : "Reviewing a shared-configuration class",
  "text" : "A configuration class in a web application is written like this and is read from every request handler:\n\n```java\npublic class AppConfig {\n    private static AppConfig instance;\n    private AppConfig() { }\n    public static AppConfig getInstance() {\n        if (instance == null) {\n            instance = new AppConfig();\n        }\n        return instance;\n    }\n}\n```\n\nWhich criticisms of this code are justified?",
  "hint" : "Consider what happens under concurrent requests, and what a unit test can control.",
  "points" : 2.0,
  "scoringType" : "ALL_OR_NOTHING",
  "randomizeOrder" : false,
  "invalid" : false,
  "answerOptions" : [ {
    "id" : 818,
    "text" : "Two request threads can both observe `instance == null` and create two configurations.",
    "explanation" : "The lazy check is a classic unsynchronised race.",
    "isCorrect" : true,
    "invalid" : false
  }, {
    "id" : 819,
    "text" : "Tests of a request handler cannot easily substitute a different configuration.",
    "explanation" : "The handler reaches for global state instead of receiving a collaborator.",
    "isCorrect" : true,
    "invalid" : false
  }, {
    "id" : 820,
    "text" : "The private constructor prevents `AppConfig` from implementing an interface.",
    "explanation" : "Constructor visibility and interface implementation are unrelated.",
    "isCorrect" : false,
    "invalid" : false
  }, {
    "id" : 821,
    "text" : "The design necessarily uses more memory than passing a configuration object around.",
    "explanation" : "One instance exists either way; memory is not the issue.",
    "isCorrect" : false,
    "invalid" : false
  } ],
  "singleChoice" : false,
